class Person
  include Enumerable
  def initialize = (@courses = [])
  def each(&block) = @courses.each(&block)   # traversal, the array is never handed out
  def courses = @courses.dup                 # or @courses.freeze at construction

  def add_course(course)
    raise ArgumentError, 'not accepted' unless course.accepted?
    @courses << course
  end

  def remove_course(course) = @courses.delete(course)
end
